// GitheftHandler is an implementation of the githeft.v1.Githeft service.
type GitheftHandler interface {
	// Notebooks: one git repository each.
	ListNotebooks(context.Context, *connect.Request[v1.ListNotebooksRequest]) (*connect.Response[v1.ListNotebooksResponse], error)
	CreateNotebook(context.Context, *connect.Request[v1.CreateNotebookRequest]) (*connect.Response[v1.Notebook], error)
	UpdateNotebook(context.Context, *connect.Request[v1.UpdateNotebookRequest]) (*connect.Response[v1.Notebook], error)
	DeleteNotebook(context.Context, *connect.Request[v1.DeleteNotebookRequest]) (*connect.Response[v1.DeleteNotebookResponse], error)
	// Remotes and credentials.
	GenerateSshKey(context.Context, *connect.Request[v1.GenerateSshKeyRequest]) (*connect.Response[v1.SshKey], error)
	ImportSshKey(context.Context, *connect.Request[v1.ImportSshKeyRequest]) (*connect.Response[v1.SshKey], error)
	GetSshKey(context.Context, *connect.Request[v1.GetSshKeyRequest]) (*connect.Response[v1.SshKey], error)
	// Checks that the remote can be reached with the given credentials, the way
	// `git ls-remote` does, before a clone or after changing the remote.
	TestRemote(context.Context, *connect.Request[v1.TestRemoteRequest]) (*connect.Response[v1.TestRemoteResponse], error)
	// Drops the remembered SSH host key of a host, after it legitimately changed.
	ForgetHostKey(context.Context, *connect.Request[v1.ForgetHostKeyRequest]) (*connect.Response[v1.ForgetHostKeyResponse], error)
	// Notes and folders.
	ListNotes(context.Context, *connect.Request[v1.ListNotesRequest]) (*connect.Response[v1.ListNotesResponse], error)
	GetNote(context.Context, *connect.Request[v1.GetNoteRequest]) (*connect.Response[v1.Note], error)
	SaveNote(context.Context, *connect.Request[v1.SaveNoteRequest]) (*connect.Response[v1.SaveNoteResponse], error)
	RenameNote(context.Context, *connect.Request[v1.RenameNoteRequest]) (*connect.Response[v1.Note], error)
	DeleteNote(context.Context, *connect.Request[v1.DeleteNoteRequest]) (*connect.Response[v1.DeleteNoteResponse], error)
	CreateFolder(context.Context, *connect.Request[v1.CreateFolderRequest]) (*connect.Response[v1.CreateFolderResponse], error)
	ListTags(context.Context, *connect.Request[v1.ListTagsRequest]) (*connect.Response[v1.ListTagsResponse], error)
	// Pins a note or changes its editor type, stored in the front matter like
	// GitJournal does (pinned: true, type: Checklist).
	UpdateNoteMeta(context.Context, *connect.Request[v1.UpdateNoteMetaRequest]) (*connect.Response[v1.Note], error)
	// Images and other files next to the notes.
	AddAttachment(context.Context, *connect.Request[v1.AddAttachmentRequest]) (*connect.Response[v1.AddAttachmentResponse], error)
	GetFile(context.Context, *connect.Request[v1.GetFileRequest]) (*connect.Response[v1.GetFileResponse], error)
	// Links between notes: [[wiki links]] and relative Markdown links.
	ResolveLink(context.Context, *connect.Request[v1.ResolveLinkRequest]) (*connect.Response[v1.ResolveLinkResponse], error)
	GetBacklinks(context.Context, *connect.Request[v1.GetBacklinksRequest]) (*connect.Response[v1.GetBacklinksResponse], error)
	// Setting up a notebook on GitHub, GitLab or a Gitea/Forgejo host
	// (Codeberg): sign in, pick or create a repository, add a deploy key.
	HostInfo(context.Context, *connect.Request[v1.HostInfoRequest]) (*connect.Response[v1.HostInfoResponse], error)
	HostLoginStart(context.Context, *connect.Request[v1.HostLoginStartRequest]) (*connect.Response[v1.HostLoginStartResponse], error)
	HostLoginPoll(context.Context, *connect.Request[v1.HostLoginPollRequest]) (*connect.Response[v1.HostLoginPollResponse], error)
	HostListRepos(context.Context, *connect.Request[v1.HostListReposRequest]) (*connect.Response[v1.HostListReposResponse], error)
	HostCreateRepo(context.Context, *connect.Request[v1.HostCreateRepoRequest]) (*connect.Response[v1.HostRepo], error)
	HostAddDeployKey(context.Context, *connect.Request[v1.HostAddDeployKeyRequest]) (*connect.Response[v1.HostAddDeployKeyResponse], error)
	// Sync: commit, fetch, merge and push.
	Sync(context.Context, *connect.Request[v1.SyncRequest]) (*connect.Response[v1.SyncStatus], error)
	GetSyncStatus(context.Context, *connect.Request[v1.GetSyncStatusRequest]) (*connect.Response[v1.SyncStatus], error)
	// Syncs every notebook that has automatic sync on, as the background job
	// does.
	SyncAll(context.Context, *connect.Request[v1.SyncAllRequest]) (*connect.Response[v1.SyncAllResponse], error)
}

